def check_equation(x, y, z):
    """Checks if x^3 + y^3 + z^3 = x^2*y^2*z^2"""
    lhs = x**3 + y**3 + z**3
    rhs = (x**2) * (y**2) * (z**2)
    return lhs == rhs

solutions = []
max_z = 5

# Iterate through all possible triples (x, y, z) satisfying 1 <= x <= y <= z <= 5
for z in range(1, max_z + 1):
    for y in range(1, z + 1):
        for x in range(1, y + 1):
            if check_equation(x, y, z):
                solutions.append((x, y, z))

print("Solutions found:", solutions)
